js:
var sc = root.querySelector('.sct-read-highlight-scroll');
var fill = root.querySelector('.sct-read-highlight-fill');
var pct = root.querySelector('.sct-read-highlight-pct');
var paras = root.querySelectorAll('.sct-read-highlight-p');
var ON = 'sct-read-highlight-on', NOW = 'sct-read-highlight-now';
var words = [], tops = [], boxH = -1, read = 0, cur = -1, ticking = false;

for (var i = 0; i < paras.length; i++) {
  var bits = paras[i].textContent.split(/\s+/);
  paras[i].textContent = '';
  for (var j = 0; j < bits.length; j++) {
    if (!bits[j]) continue;
    var s = document.createElement('span');
    s.className = 'sct-read-highlight-w';
    s.textContent = bits[j];
    paras[i].appendChild(s);
    paras[i].appendChild(document.createTextNode(' '));
    words.push(s);
  }
}

function measure() {
  tops.length = 0;
  for (var k = 0; k < words.length; k++) tops.push(words[k].offsetTop + words[k].offsetHeight * 0.7);
  boxH = sc.clientHeight;
}

function apply(n) {
  var k;
  if (n > read) { for (k = read; k < n; k++) words[k].classList.add(ON); }
  else if (n < read) { for (k = n; k < read; k++) words[k].classList.remove(ON); }
  read = n;
  var c = n - 1;
  if (c !== cur) {
    if (words[cur]) words[cur].classList.remove(NOW);
    if (words[c]) words[c].classList.add(NOW);
    cur = c;
  }
  var p = words.length ? n / words.length : 0;
  fill.style.width = (p * 100).toFixed(1) + '%';
  pct.textContent = Math.round(p * 100) + '% read';
}

function update() {
  if (!tops.length || sc.clientHeight !== boxH) measure();
  var line = sc.scrollTop + sc.clientHeight * 0.42;
  var n = 0;
  while (n < tops.length && tops[n] <= line) n++;
  if (sc.scrollTop >= sc.scrollHeight - sc.clientHeight - 2) n = words.length;
  apply(n);
}

function onScroll() {
  if (ticking) return;
  ticking = true;
  requestAnimationFrame(function () {
    if (!root.isConnected) return;
    ticking = false;
    update();
  });
}

sc.addEventListener('scroll', onScroll, { passive: true });
onScroll();

