js:
var sc = root.querySelector('.sct-char-decode-scroll');
var counter = root.querySelector('.sct-char-decode-count');
var rows = Array.prototype.slice.call(root.querySelectorAll('.sct-char-decode-row'));
var POOL = 'ABCDEF0123456789#%&$@/\\<>*+=-';
var GLYPH = '▓▒░▚▞';
var reduced = false;
try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) {}
var active = [], running = false;

var items = rows.map(function (row) {
  var el = row.querySelector('.sct-char-decode-txt');
  var full = el.getAttribute('data-text') || '';
  el.textContent = mask(full, 0);
  return { row: row, el: el, full: full, t: 0, done: false };
});

function mask(str, shown) {
  var out = str.slice(0, shown);
  for (var i = shown; i < str.length; i++) {
    if (str.charAt(i) === ' ') { out += ' '; continue; }
    var p = (i % 3 === 0 ? GLYPH : POOL);
    out += p.charAt(Math.floor(Math.random() * p.length));
  }
  return out;
}

function done() {
  var n = 0;
  for (var i = 0; i < items.length; i++) if (items[i].done) n++;
  counter.textContent = n + '/' + items.length;
}

function tick() {
  if (!root.isConnected) { running = false; return; }
  var still = [];
  for (var i = 0; i < active.length; i++) {
    var it = active[i];
    it.t += 0.055;
    var shown = Math.min(it.full.length, Math.round(it.t * it.full.length));
    it.el.textContent = mask(it.full, shown);
    if (shown >= it.full.length) {
      it.el.textContent = it.full;
      it.done = true;
      it.row.classList.remove('sct-char-decode-live');
      it.row.classList.add('sct-char-decode-done');
    } else still.push(it);
  }
  active = still;
  done();
  if (active.length) requestAnimationFrame(tick); else running = false;
}

function start(it) {
  if (it.done || active.indexOf(it) > -1) return;
  if (reduced) {
    it.el.textContent = it.full;
    it.done = true;
    it.row.classList.add('sct-char-decode-done');
    done();
    return;
  }
  it.t = 0;
  it.row.classList.add('sct-char-decode-live');
  active.push(it);
  if (!running) { running = true; requestAnimationFrame(tick); }
}

var io = new IntersectionObserver(function (entries) {
  for (var i = 0; i < entries.length; i++) {
    var it = items[rows.indexOf(entries[i].target)];
    if (!it) continue;
    if (entries[i].isIntersecting) start(it);
  }
}, { root: sc, rootMargin: '0px 0px -28% 0px', threshold: 0.6 });

for (var k = 0; k < rows.length; k++) io.observe(rows[k]);
done();

