js:
var sc = root.querySelector('.sct-scrub-typer-scroll');
var out = root.querySelector('.sct-scrub-typer-out');
var count = root.querySelector('.sct-scrub-typer-count');
var LINES = [
  { c: 'cmd', t: './release.sh --tag v2.4.0' },
  { c: 'step', t: 'bundling 118 modules' },
  { c: 'step', t: 'signing artifacts' },
  { c: 'warn', t: 'cache miss, rebuilding' },
  { c: 'good', t: 'built in 4.2s' },
  { c: 'cmd', t: 'ship --to production' },
  { c: 'step', t: 'draining connections' },
  { c: 'good', t: 'live on 12 edges' }
];
var nodes = [], starts = [], total = 0, ticking = false, last = -1;

for (var i = 0; i < LINES.length; i++) {
  var d = document.createElement('div');
  d.className = 'sct-scrub-typer-ln sct-scrub-typer-' + LINES[i].c;
  var span = document.createElement('span');
  d.appendChild(span);
  out.appendChild(d);
  nodes.push(span);
  starts.push(total);
  total += LINES[i].t.length + 1;
}
var caret = document.createElement('span');
caret.className = 'sct-scrub-typer-caret';
caret.setAttribute('aria-hidden', 'true');
out.firstChild.appendChild(caret);

function render(n) {
  if (n === last) return;
  last = n;
  var host = out.firstChild, front = 0, i, len;
  for (i = 0; i < LINES.length; i++) {
    len = Math.max(0, Math.min(LINES[i].t.length, n - starts[i]));
    if (nodes[i].textContent.length !== len) nodes[i].textContent = LINES[i].t.slice(0, len);
    if (len > 0) { front = i; host = nodes[i].parentNode; }
  }
  for (i = 0; i < LINES.length; i++) {
    nodes[i].parentNode.classList.toggle('sct-scrub-typer-idle', i > front && nodes[i].textContent === '');
  }
  if (caret.parentNode !== host) host.appendChild(caret);
  count.textContent = n + ' / ' + total;
  root.classList.toggle('sct-scrub-typer-typing', n > 0 && n < total);
}

function update() {
  var max = sc.scrollHeight - sc.clientHeight;
  var p = max > 0 ? sc.scrollTop / max : 0;
  p = Math.max(0, Math.min(1, p * 1.08));
  if (p > 0.01) root.classList.add('sct-scrub-typer-moved');
  render(Math.round(p * total));
}

function onScroll() {
  if (ticking) return;
  ticking = true;
  requestAnimationFrame(function () {
    if (!root.isConnected) return;
    ticking = false;
    update();
  });
}

sc.addEventListener('scroll', onScroll, { passive: true });
render(0);
onScroll();

