var sc = root.querySelector('.sct-mask-fill-scroll');
var num = root.querySelector('.sct-mask-fill-num');
var ticking = false, shown = -1;

function update() {
  var max = sc.scrollHeight - sc.clientHeight;
  var p = max > 0 ? sc.scrollTop / max : 0;
  p = Math.max(0, Math.min(1, p));
  root.style.setProperty('--sctmf-p', p.toFixed(4));
