  if (!root.isConnected) return;
  if (root.querySelector('[data-line].is-in')) return;
  var edge = sc.scrollTop + sc.clientHeight;
  for (var i = 0; i < lines.length; i++) {
    if (lines[i].offsetTop < edge) lines[i].classList.add('is-in');
  }
  tally();
}, 900);

