var sc = root.querySelector('[data-scroll]');
var cards = root.querySelectorAll('[data-q]');
var dots = root.querySelectorAll('[data-dot]');
var idx = root.querySelector('[data-idx]');
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var live = -1;

function two(n) { return (n < 10 ? '0' : '') + n; }

var frame = 0;
function draw() {
  if (!root.isConnected) return;
  frame = 0;
  var mid = sc.scrollTop + sc.clientHeight / 2;
  var best = 0, bestD = Infinity;
  for (var i = 0; i < cards.length; i++) {
    var c = cards[i];
    var d = Math.abs(c.offsetTop + c.offsetHeight / 2 - mid);
    if (d < bestD) { bestD = d; best = i; }
  }
  if (best === live) return;
  live = best;
  for (var j = 0; j < cards.length; j++) {
    cards[j].classList.toggle('is-live', j === live);
    if (dots[j]) {
      dots[j].classList.toggle('is-live', j === live);
      dots[j].setAttribute('aria-current', j === live ? 'true' : 'false');
    }
  }
  idx.textContent = two(live + 1) + ' / ' + two(cards.length);
}
function schedule() { if (!frame) frame = requestAnimationFrame(draw); }

sc.addEventListener('scroll', schedule, { passive: true });

for (var d = 0; d < dots.length; d++) {
  dots[d].addEventListener('click', function (ev) {
    var n = parseInt(ev.currentTarget.getAttribute('data-i'), 10) || 0;
    var card = cards[n];
    if (!card) return;
    var to = card.offsetTop + card.offsetHeight / 2 - sc.clientHeight / 2;
    sc.scrollTo({ top: to < 0 ? 0 : to, behavior: calm ? 'auto' : 'smooth' });
  });
}
draw();

