js:
var sc = root.querySelector('[data-scroll]');
var stack = root.querySelector('[data-stack]');
var focus = root.querySelector('[data-focus]');
var words = root.querySelectorAll('[data-word]');
var calm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var mids = [];
var last = sc.scrollTop, vel = 0, raf = 0, live = -1;

function measure() {
  mids.length = 0;
  for (var i = 0; i < words.length; i++) mids.push(words[i].offsetTop + words[i].offsetHeight / 2);
}

function paint() {
  var mid = sc.scrollTop + sc.clientHeight / 2;
  var half = (sc.clientHeight / 2) || 1;
  var best = 0, bestD = Infinity;
  for (var i = 0; i < words.length; i++) {
    var w = words[i];
    var d = (mids[i] - mid) / half;
    var ad = Math.abs(d);
    if (ad < bestD) { bestD = ad; best = i; }
    var k = d < -1.15 ? -1.15 : (d > 1.15 ? 1.15 : d);
    if (calm) {
      w.style.transform = 'none';
      w.style.opacity = (1 - Math.min(ad, 1) * 0.6).toFixed(3);
    } else {
      w.style.transform = 'translateZ(' + (-Math.min(ad, 1.15) * 120).toFixed(1) + 'px) rotateX(' + (k * -52).toFixed(2) + 'deg)';
      w.style.opacity = (1 - Math.min(ad, 1.1) * 0.72).toFixed(3);
    }
  }
  if (best !== live) {
    live = best;
    for (var j = 0; j < words.length; j++) words[j].classList.toggle('is-live', j === live);
    focus.textContent = words[live].textContent;
  }
  if (!calm) {
    var sk = vel * 0.05;
    sk = sk < -6 ? -6 : (sk > 6 ? 6 : sk);
    stack.style.transform = 'skewY(' + sk.toFixed(2) + 'deg)';
  }
}

function tick() {
  if (!root.isConnected) return;
  var now = sc.scrollTop;
  vel = vel * 0.82 + (now - last) * 0.18;
  last = now;
  paint();
  if (Math.abs(vel) > 0.05) {
    raf = requestAnimationFrame(tick);
  } else {
    vel = 0;
    if (!calm) stack.style.transform = 'skewY(0deg)';
    raf = 0;
  }
}

sc.addEventListener('scroll', function () {
  if (!raf) raf = requestAnimationFrame(tick);
}, { passive: true });

measure();
paint();
if (window.ResizeObserver) {
  var ro = new ResizeObserver(function () { measure(); paint(); });
  ro.observe(sc);
}

