js:
var sc = root.querySelector('[data-scroll]');
var pct = root.querySelector('[data-pct]');
var mode = root.querySelector('[data-mode]');
var native = !!(window.CSS && CSS.supports && CSS.supports('animation-timeline', 'scroll()'));

if (native) {
  root.classList.add('is-native');
  mode.textContent = 'scroll() timeline';
} else {
  mode.textContent = 'scroll fallback';
}

var frame = 0;
function draw() {
  if (!root.isConnected) return;
  frame = 0;
  var max = sc.scrollHeight - sc.clientHeight;
  var p = max > 0 ? sc.scrollTop / max : 0;
  p = p < 0 ? 0 : (p > 1 ? 1 : p);
  root.style.setProperty('--p', p.toFixed(4));
  pct.textContent = Math.round(p * 100) + '%';
}
function schedule() { if (!frame) frame = requestAnimationFrame(draw); }

sc.addEventListener('scroll', schedule, { passive: true });
draw();
if (window.ResizeObserver) {
  var ro = new ResizeObserver(schedule);
  ro.observe(sc);
}
